import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_pipeline.h>
#include <vector>

template <typename scalar_t>
__global__ void conv_transpose3d_direct_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    const int batch, const int inC, const int outC,
    const int inD, const int inH, const int inW,
    const int outD, const int outH, const int outW,
    const int kD, const int kH, const int kW,
    const int sD, const int sH, const int sW,
    const int pD, const int pH, const int pW,
    const int groups)
{
    const long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long total = (long long)batch * outC * outD * outH * outW;
    if (idx >= total) return;
    const int ow = (int)(idx % outW);
    const int oh = (int)((idx / outW) % outH);
    const int od = (int)((idx / ((long long)outW * outH)) % outD);
    const int oc = (int)((idx / ((long long)outW * outH * outD)) % outC);
    const int b  = (int)(idx / ((long long)outW * outH * outD * outC));
    const int outC_per_group = outC / groups;
    const int inC_per_group = inC / groups;
    const int g = oc / outC_per_group;
    const int oc_local = oc - g * outC_per_group;
    scalar_t acc = (bias != nullptr) ? bias[oc] : (scalar_t)0;
    for (int ic = g * inC_per_group; ic < (g + 1) * inC_per_group; ++ic) {
        for (int kd = 0; kd < kD; ++kd) {
            const int td = od + pD - kd;
            if (td % sD != 0) continue;
            const int id = td / sD;
            if (id < 0 || id >= inD) continue;
            for (int kh = 0; kh < kH; ++kh) {
                const int th = oh + pH - kh;
                if (th % sH != 0) continue;
                const int ih = th / sH;
                if (ih < 0 || ih >= inH) continue;
                for (int kw = 0; kw < kW; ++kw) {
                    const int tw = ow + pW - kw;
                    if (tw % sW != 0) continue;
                    const int iw = tw / sW;
                    if (iw < 0 || iw >= inW) continue;
                    const long long in_idx =
                        ((((long long)b * inC + ic) * inD + id) * inH + ih) * inW + iw;
                    const long long w_idx =
                        ((((long long)ic * outC_per_group + oc_local) * kD + kd) * kH + kh) * kW + kw;
                    acc += input[in_idx] * weight[w_idx];
                }
            }
        }
    }
    output[idx] = acc;
}
__global__ void __launch_bounds__(256, 3) conv_transpose3d_tiled_k3_s1_p0_g1_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch, const int inC, const int outC,
    const int inD, const int inH, const int inW,
    const int outD, const int outH, const int outW)
{
    constexpr int TILE = 8;
    constexpr int IP = TILE + 2;
    constexpr int OC_BLOCK = 8;
    constexpr int IC_CHUNK = 2;
    constexpr int K = 3;
    constexpr int KKK = K * K * K;
    constexpr int XT = TILE / 2;
    constexpr int IN_FLOATS = IC_CHUNK * IP * IP * IP;
    constexpr int W_FLOATS = KKK * IC_CHUNK * OC_BLOCK;
    extern __shared__ __align__(16) float smem[];
    constexpr int STAGE_FLOATS = IN_FLOATS + W_FLOATS;
    float* s_in0 = smem;
    float* s_w0 = smem + IN_FLOATS;
    float* s_in1 = smem + STAGE_FLOATS;
    float* s_w1 = smem + STAGE_FLOATS + IN_FLOATS;
    const int tw = (outW + TILE - 1) / TILE;
    const int th = (outH + TILE - 1) / TILE;
    const int td = (outD + TILE - 1) / TILE;
    const int oc_blocks = (outC + OC_BLOCK - 1) / OC_BLOCK;
    int t = (int)blockIdx.x;
    const int owb = t % tw; t /= tw;
    const int ohb = t % th; t /= th;
    const int odb = t % td; t /= td;
    const int ocb = t % oc_blocks;
    const int b = t / oc_blocks;
    const int od0 = odb * TILE;
    const int oh0 = ohb * TILE;
    const int ow0 = owb * TILE;
    const int oc0 = ocb * OC_BLOCK;
    const int id0 = od0 - (K - 1);
    const int ih0 = oh0 - (K - 1);
    const int iw0 = ow0 - (K - 1);
    const int q = (int)threadIdx.x;
    const int lz = q / (TILE * XT);
    const int qr = q % (TILE * XT);
    const int ly = qr / XT;
    const int lx = (qr % XT) * 2;
    const int gz = od0 + lz;
    const int gy = oh0 + ly;
    const int gx0 = ow0 + lx;
    const bool valid0 = (gz < outD) && (gy < outH) && (gx0 < outW);
    const bool valid1 = (gz < outD) && (gy < outH) && ((gx0 + 1) < outW);
    float acc0[OC_BLOCK];
    float acc1[OC_BLOCK];
    #pragma unroll
    for (int oc = 0; oc < OC_BLOCK; ++oc) { acc0[oc] = 0.0f; acc1[oc] = 0.0f; }
    auto load_stage = [&](int ic0, float* s_in_b, float* s_w_b) {
        for (int i = (int)threadIdx.x; i < IN_FLOATS; i += 256) {
            const int ic = i / (IP * IP * IP);
            const int r0 = i % (IP * IP * IP);
            const int iz = r0 / (IP * IP);
            const int r1 = r0 % (IP * IP);
            const int iy = r1 / IP;
            const int ix = r1 % IP;
            const int gic = ic0 + ic;
            const int id = id0 + iz;
            const int ih = ih0 + iy;
            const int iw = iw0 + ix;
            if (gic < inC && id >= 0 && id < inD && ih >= 0 && ih < inH && iw >= 0 && iw < inW) {
                const long long in_idx = ((((long long)b * inC + gic) * inD + id) * inH + ih) * inW + iw;
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
                __pipeline_memcpy_async(s_in_b + i, input + in_idx, 4);
#else
                s_in_b[i] = input[in_idx];
#endif
            } else {
                s_in_b[i] = 0.0f;
            }
        }
        for (int i = (int)threadIdx.x; i < W_FLOATS; i += 256) {
            const int k = i / (IC_CHUNK * OC_BLOCK);
            const int r = i % (IC_CHUNK * OC_BLOCK);
            const int ic = r / OC_BLOCK;
            const int oc = r % OC_BLOCK;
            const int gic = ic0 + ic;
            const int goc = oc0 + oc;
            if (gic < inC && goc < outC) {
                const long long w_idx = (((long long)gic * outC + goc) * KKK) + k;
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
                __pipeline_memcpy_async(s_w_b + i, weight + w_idx, 4);
#else
                s_w_b[i] = weight[w_idx];
#endif
            } else {
                s_w_b[i] = 0.0f;
            }
        }
    };
    int buf = 0;
    load_stage(0, s_in0, s_w0);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    __pipeline_commit();
#endif
    for (int ic0 = 0; ic0 < inC; ic0 += IC_CHUNK) {
        const bool has_next = (ic0 + IC_CHUNK) < inC;
        float* s_in_c = (buf == 0) ? s_in0 : s_in1;
        float* s_w_c = (buf == 0) ? s_w0 : s_w1;
        float* s_in_n = (buf == 0) ? s_in1 : s_in0;
        float* s_w_n = (buf == 0) ? s_w1 : s_w0;
        if (has_next) load_stage(ic0 + IC_CHUNK, s_in_n, s_w_n);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
        __pipeline_commit();
        if (has_next) {
            __pipeline_wait_prior(1);
        } else {
            __pipeline_wait_prior(0);
        }
#endif
        __syncthreads();
        #pragma unroll
        for (int ic = 0; ic < IC_CHUNK; ++ic) {
            #pragma unroll
            for (int kd = 0; kd < K; ++kd) {
                #pragma unroll
                for (int kh = 0; kh < K; ++kh) {
                    #pragma unroll
                    for (int kw = 0; kw < K; ++kw) {
                        const int k = (kd * K + kh) * K + kw;
                        const int ib = ((ic * IP + (lz + (K - 1) - kd)) * IP + (ly + (K - 1) - kh)) * IP + (lx + (K - 1) - kw);
                        const float xv0 = s_in_c[ib];
                        const float xv1 = s_in_c[ib + 1];
                        const int wbase = (k * IC_CHUNK + ic) * OC_BLOCK;
                        const float4 wlo = *reinterpret_cast<const float4*>(s_w_c + wbase);
                        const float4 whi = *reinterpret_cast<const float4*>(s_w_c + wbase + 4);
                        acc0[0] += xv0 * wlo.x;
                        acc0[1] += xv0 * wlo.y;
                        acc0[2] += xv0 * wlo.z;
                        acc0[3] += xv0 * wlo.w;
                        acc0[4] += xv0 * whi.x;
                        acc0[5] += xv0 * whi.y;
                        acc0[6] += xv0 * whi.z;
                        acc0[7] += xv0 * whi.w;
                        acc1[0] += xv1 * wlo.x;
                        acc1[1] += xv1 * wlo.y;
                        acc1[2] += xv1 * wlo.z;
                        acc1[3] += xv1 * wlo.w;
                        acc1[4] += xv1 * whi.x;
                        acc1[5] += xv1 * whi.y;
                        acc1[6] += xv1 * whi.z;
                        acc1[7] += xv1 * whi.w;
                    }
                }
            }
        }
        __syncthreads();
        buf ^= 1;
    }
    if (valid0) {
        const long long cstride = (long long)outD * outH * outW;
        const long long out_base = ((((long long)b * outC) * outD + gz) * outH + gy) * outW + gx0;
        #pragma unroll
        for (int oc = 0; oc < OC_BLOCK; ++oc) {
            const int goc = oc0 + oc;
            if (goc < outC) {
                const float bv = (bias != nullptr) ? bias[goc] : 0.0f;
                const long long oidx = out_base + (long long)goc * cstride;
                output[oidx] = acc0[oc] + bv;
                if (valid1) output[oidx + 1] = acc1[oc] + bv;
            }
        }
    }
}
torch::Tensor conv_transpose3d(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t output_padding, int64_t groups)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "input must be 5D (N, C, D, H, W)");
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    const int batch = (int)input_c.size(0);
    const int inC   = (int)input_c.size(1);
    const int inD   = (int)input_c.size(2);
    const int inH   = (int)input_c.size(3);
    const int inW   = (int)input_c.size(4);
    const int outC  = (int)weight_c.size(1) * (int)groups;
    const int kD    = (int)weight_c.size(2);
    const int kH    = (int)weight_c.size(3);
    const int kW    = (int)weight_c.size(4);
    const int sD = (int)stride, sH = (int)stride, sW = (int)stride;
    const int pD = (int)padding, pH = (int)padding, pW = (int)padding;
    const int outD = (inD - 1) * sD - 2 * pD + kD + (int)output_padding;
    const int outH = (inH - 1) * sH - 2 * pH + kH + (int)output_padding;
    const int outW = (inW - 1) * sW - 2 * pW + kW + (int)output_padding;
    auto output = torch::empty({batch, outC, outD, outH, outW}, input_c.options());
    const long long total = (long long)batch * outC * outD * outH * outW;
    if (total == 0) return output;
    torch::Tensor bias_c;
    const bool fast_path =
        input_c.scalar_type() == at::kFloat &&
        groups == 1 &&
        sD == 1 && sH == 1 && sW == 1 &&
        pD == 0 && pH == 0 && pW == 0 &&
        output_padding == 0 &&
        kD == 3 && kH == 3 && kW == 3;
    if (fast_path) {
        constexpr int TILE = 8;
        constexpr int OC_BLOCK = 8;
        const int threads = 256;
        const int tw = (outW + TILE - 1) / TILE;
        const int th = (outH + TILE - 1) / TILE;
        const int td = (outD + TILE - 1) / TILE;
        const int oc_blocks = (outC + OC_BLOCK - 1) / OC_BLOCK;
        const long long blocks_ll = (long long)batch * oc_blocks * td * th * tw;
        if (blocks_ll <= 2147483647LL) {
            const float* bias_ptr = nullptr;
            if (bias.has_value() && bias.value().defined()) {
                bias_c = bias.value().contiguous();
                bias_ptr = bias_c.data_ptr<float>();
            }
            const size_t smem_bytes = (size_t)2 * (2 * 10 * 10 * 10 + 27 * 2 * 8) * sizeof(float);
            conv_transpose3d_tiled_k3_s1_p0_g1_kernel<<<(unsigned int)blocks_ll, threads, smem_bytes, at::cuda::getCurrentCUDAStream()>>>(
                input_c.data_ptr<float>(),
                weight_c.data_ptr<float>(),
                bias_ptr,
                output.data_ptr<float>(),
                batch, inC, outC,
                inD, inH, inW,
                outD, outH, outW);
            C10_CUDA_KERNEL_LAUNCH_CHECK();
            return output;
        }
    }
    const int threads = 256;
    const long long blocks = (total + threads - 1) / threads;
    AT_DISPATCH_FLOATING_TYPES(input_c.scalar_type(), "conv_transpose3d_cuda", [&] {
        const scalar_t* bias_ptr = nullptr;
        if (bias.has_value() && bias.value().defined()) {
            bias_c = bias.value().contiguous();
            bias_ptr = bias_c.data_ptr<scalar_t>();
        }
        conv_transpose3d_direct_kernel<scalar_t><<<(unsigned int)blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            input_c.data_ptr<scalar_t>(),
            weight_c.data_ptr<scalar_t>(),
            bias_ptr,
            output.data_ptr<scalar_t>(),
            batch, inC, outC,
            inD, inH, inW,
            outD, outH, outW,
            kD, kH, kW,
            sD, sH, sW,
            pD, pH, pW,
            (int)groups);
    });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""

cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t output_padding, int64_t groups);
"""

conv_transpose3d_ext = load_inline(
    name="conv_transpose3d_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution backed by a single custom CUDA kernel.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias)
        self.stride = self.conv_transpose3d.stride[0]
        self.padding = self.conv_transpose3d.padding[0]
        self.output_padding = self.conv_transpose3d.output_padding[0]
        self.groups = self.conv_transpose3d.groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose3d_ext.conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            self.conv_transpose3d.bias,
            self.stride,
            self.padding,
            self.output_padding,
            self.groups)

