#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

template <typename scalar_t>
__global__ void conv_transpose3d_direct_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    const int batch, const int inC, const int outC,
    const int inD, const int inH, const int inW,
    const int outD, const int outH, const int outW,
    const int kD, const int kH, const int kW,
    const int sD, const int sH, const int sW,
    const int pD, const int pH, const int pW,
    const int groups)
{
    const long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long total = (long long)batch * outC * outD * outH * outW;
    if (idx >= total) return;
    const int ow = (int)(idx % outW);
    const int oh = (int)((idx / outW) % outH);
    const int od = (int)((idx / ((long long)outW * outH)) % outD);
    const int oc = (int)((idx / ((long long)outW * outH * outD)) % outC);
    const int b  = (int)(idx / ((long long)outW * outH * outD * outC));
    const int outC_per_group = outC / groups;
    const int inC_per_group = inC / groups;
    const int g = oc / outC_per_group;
    const int oc_local = oc - g * outC_per_group;
    scalar_t acc = (bias != nullptr) ? bias[oc] : (scalar_t)0;
    for (int ic = g * inC_per_group; ic < (g + 1) * inC_per_group; ++ic) {
        for (int kd = 0; kd < kD; ++kd) {
            const int td = od + pD - kd;
            if (td % sD != 0) continue;
            const int id = td / sD;
            if (id < 0 || id >= inD) continue;
            for (int kh = 0; kh < kH; ++kh) {
                const int th = oh + pH - kh;
                if (th % sH != 0) continue;
                const int ih = th / sH;
                if (ih < 0 || ih >= inH) continue;
                for (int kw = 0; kw < kW; ++kw) {
                    const int tw = ow + pW - kw;
                    if (tw % sW != 0) continue;
                    const int iw = tw / sW;
                    if (iw < 0 || iw >= inW) continue;
                    const long long in_idx =
                        ((((long long)b * inC + ic) * inD + id) * inH + ih) * inW + iw;
                    const long long w_idx =
                        ((((long long)ic * outC_per_group + oc_local) * kD + kd) * kH + kh) * kW + kw;
                    acc += input[in_idx] * weight[w_idx];
                }
            }
        }
    }
    output[idx] = acc;
}
__global__ void __launch_bounds__(256, 3) conv_transpose3d_tiled_k3_s1_p0_g1_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch, const int inC, const int outC,
    const int inD, const int inH, const int inW,
    const int outD, const int outH, const int outW)
{
    constexpr int TILE = 8;
    constexpr int IP = TILE + 2;
    constexpr int OC_BLOCK = 8;
    constexpr int IC_CHUNK = 4;
    constexpr int K = 3;
    constexpr int KKK = K * K * K;
    constexpr int XT = TILE / 2;
    constexpr int IN_FLOATS = IC_CHUNK * IP * IP * IP;
    constexpr int W_FLOATS = KKK * IC_CHUNK * OC_BLOCK;
    extern __shared__ __align__(16) float smem[];
    float* s_in = smem;
    float* s_w = smem + IN_FLOATS;
    const int tw = (outW + TILE - 1) / TILE;
    const int th = (outH + TILE - 1) / TILE;
    const int td = (outD + TILE - 1) / TILE;
    const int oc_blocks = (outC + OC_BLOCK - 1) / OC_BLOCK;
    int t = (int)blockIdx.x;
    const int owb = t % tw; t /= tw;
    const int ohb = t % th; t /= th;
    const int odb = t % td; t /= td;
    const int ocb = t % oc_blocks;
    const int b = t / oc_blocks;
    const int od0 = odb * TILE;
    const int oh0 = ohb * TILE;
    const int ow0 = owb * TILE;
    const int oc0 = ocb * OC_BLOCK;
    const int id0 = od0 - (K - 1);
    const int ih0 = oh0 - (K - 1);
    const int iw0 = ow0 - (K - 1);
    const int q = (int)threadIdx.x;
    const int lz = q / (TILE * XT);
    const int qr = q % (TILE * XT);
    const int ly = qr / XT;
    const int lx = (qr % XT) * 2;
    const int gz = od0 + lz;
    const int gy = oh0 + ly;
    const int gx0 = ow0 + lx;
    const bool valid0 = (gz < outD) && (gy < outH) && (gx0 < outW);
    const bool valid1 = (gz < outD) && (gy < outH) && ((gx0 + 1) < outW);
    float acc0[OC_BLOCK];
    float acc1[OC_BLOCK];
    #pragma unroll
    for (int oc = 0; oc < OC_BLOCK; ++oc) { acc0[oc] = 0.0f; acc1[oc] = 0.0f; }
    for (int ic0 = 0; ic0 < inC; ic0 += IC_CHUNK) {
        for (int i = (int)threadIdx.x; i < IN_FLOATS; i += 256) {
            const int ic = i / (IP * IP * IP);
            const int r0 = i % (IP * IP * IP);
            const int iz = r0 / (IP * IP);
            const int r1 = r0 % (IP * IP);
            const int iy = r1 / IP;
            const int ix = r1 % IP;
            const int gic = ic0 + ic;
            const int id = id0 + iz;
            const int ih = ih0 + iy;
            const int iw = iw0 + ix;
            float v = 0.0f;
            if (gic < inC && id >= 0 && id < inD && ih >= 0 && ih < inH && iw >= 0 && iw < inW) {
                const long long in_idx = ((((long long)b * inC + gic) * inD + id) * inH + ih) * inW + iw;
                v = input[in_idx];
            }
            s_in[i] = v;
        }
        for (int i = (int)threadIdx.x; i < W_FLOATS; i += 256) {
            const int k = i / (IC_CHUNK * OC_BLOCK);
            const int r = i % (IC_CHUNK * OC_BLOCK);
            const int ic = r / OC_BLOCK;
            const int oc = r % OC_BLOCK;
            const int gic = ic0 + ic;
            const int goc = oc0 + oc;
